begin;
with j as (select * from jsonb_to_recordset($law7d0025$[{"code_id":"GK_RF","article_number":"350.1","version_date":"1994-11-30","article_text":"1. В случае, если взыскание на заложенное имущество обращается во внесудебном порядке, его реализация осуществляется посредством продажи с торгов, проводимых в соответствии с правилами, предусмотренными настоящим Кодексом или соглашением между залогодателем и залогодержателем.\n\n2. Если залогодателем является лицо, осуществляющее предпринимательскую деятельность, соглашением между залогодателем и залогодержателем может быть также предусмотрено, что реализация заложенного имущества осуществляется путем:\n\nоставления залогодержателем предмета залога за собой, в том числе посредством поступления предмета залога в собственность залогодержателя, по цене и на иных условиях, которые определены указанным соглашением, но не ниже рыночной стоимости;\n\nпродажи предмета залога залогодержателем другому лицу по цене не ниже рыночной стоимости с удержанием из вырученных денег суммы обеспеченного залогом об\n\nязательства.\n\nВ случае, если стоимость оставляемого за залогодержателем или отчуждаемого третьему лицу имущества превышает размер неисполненного обязательства, обеспеченного залогом, разница подлежит выплате залогодателю.\n\n3. Если при обращении взыскания на заложенное имущество во внесудебном порядке доказано нарушение прав залогодателя или наличие существенного риска такого нарушения, суд может прекратить по требованию залогодателя обращение взыскания на предмет залога во внесудебном порядке и вынести решение об обращении взыскания на предмет залога путем продажи заложенного имущества с публичных торгов (статья 350).\n\n4. В целях реализации заложенного имущества залогодержатель вправе совершать необходимые для этого сделки, а также требовать передачи ему заложенного имущества залогодателем.\n\nЕсли заложенная движимая вещь, оставленная у залогодателя, передана им во владение или в пользование третьему лицу, залогодержатель вправе потребовать от этого лица передачи ему предмета залога.\n\nВ случае отказа передать залогодержателю заложенное имущество для целей его реализации предмет залога может быть изъят и передан залогодержателю по исполнительной надписи нотариуса в соответствии с законодательством о нотариате.\n\n5. Если в соответствии с условиями соглашения залогодателя с залогодержателем реализация заложенного имущества, не относящегося к недвижимым вещам, осуществляется путем продажи залогодержателем этого имущества другому лицу, залогодержатель обязан направить залогодателю заключенный с таким лицом договор купли-продажи.","article_title":"Статья 350.1. Реализация заложенного имущества при обращении на него взыскания во внесудебном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94c38d23bfcd5ecae61061e615f012c4c1e29719cb48c41b1f900a57eade7eca"},{"code_id":"GK_RF","article_number":"350.2","version_date":"1994-11-30","article_text":"1. При реализации заложенного имущества, не относящегося к недвижимым вещам, с публичных торгов (реализация заложенного имущества с публичных торгов) на основании решения суда судебный пристав - исполнитель обязан направить не позднее чем за десять дней до даты проведения торгов залогодержателю, залогодателю и должнику по основному обязательству уведомление в письменной форме о дате, времени и месте проведения торгов. При реализации заложенного имущества с торгов, проводимых при обращении взыскания на имущество во внесудебном порядке, обязанность по уведомлению залогодателя и должника несет залогодержатель.\n\n2. При реализации заложенного имущества, не относящегося к недвижимым вещам, с публичных торгов на основании решения суда или с торгов, проводимых при обращении взыскания на это имущество во внесудебном порядке, организатор торгов объявляет их не состоявшимися в случаях, если:\n\n1) на торги явилось менее двух покупателей;\n\n2) на торгах не сделана надбавка против начальной продажной цены заложенного имущества;\n\n3) лицо, выигравшее торги, не внесло покупную цену в установленный срок. Торги должны быть объявлены несостоявшимися не позднее чем на следующий день после того, как имело место какое-либо из указанных обстоятельств.\n\n3. Залогодержатель и залогодатель вправе выступать участниками торгов, проводимых на основании решения суда или при обращении взыскания на заложенное имущество во внесудебном порядке. В случае, если залогодержатель выиграл торги, подлежащая уплате им покупная цена зачитывается в счет погашения обязательства, обеспеченного залогом.\n\nПравила, предусмотренные абзацем первым настоящего пункта, применяются в случае оставления залогодержателем предмета залога за собой при обращении взыскания на заложенное имущество во внесудебном порядке.\n\n4. В течение десяти дней после объявления торгов несостоявшимися залогодержатель вправе приобрести по соглашению с залогодателем заложенное имущество, не относящееся к недвижимым вещам, и зачесть в счет покупной цены свои требования, обеспеченные залогом. К такому соглашению применяются правила о договоре купли-продажи.\n\nЕсли соглашение о приобретении имущества залогодержателем, предусмотренное настоящим пунктом, не состоялось, не позднее чем через месяц после первых торгов проводятся повторные торги. Начальная продажная цена заложенного имущества на повторных торгах, если их проведение вызвано причинами, указанными в подпунктах 1 и 2 пункта 2 настоящей статьи, снижается на пятнадцать процентов. При реализации заложенного имущества, не относящегося к недвижимым вещам, с торгов, проводимых при обращении взыскания на это имущество во внесудебном порядке, соглашением сторон может быть предусмотрено, что, если торги были объявлены не состоявшимися по указанным причинам, повторные торги проводятся путем последовательного снижения цены от начальной продажной цены на первых торгах.\n\n5. При объявлении несостоявшимися повторных торгов залогодержатель вправе оставить предмет залога за собой с оценкой его в сумме на десять процентов ниже начальной продажной цены на повторных торгах, если более высокая оценка не установлена соглашением сторон.\n\nЗалогодержатель считается воспользовавшимся указанным правом, когда в течение месяца со дня объявления повторных торгов несостоявшимися направит залогодателю и организатору торгов или, если обращение взыскания осуществлялось в судебном порядке, залогодателю, организатору торгов и судебному приставу - исполнителю заявление в письменной форме об оставлении имущества за собой.\n\nС момента получения в письменной форме залогодателем заявления залогодержателя об оставлении имущества за собой залогодержатель, которому движимая вещь была передана по договору залога, приобретает право собственности на предмет залога, оставленный им за собой, если законом не установлен иной момент возникновения права собственности на движимые вещи соответствующего вида.\n\nЗалогодержатель, оставивший заложенное имущество за собой, вправе требовать передачи ему этого имущества, если оно находится у иного лица.\n\n6. Если залогодержатель не воспользуется правом оставить за собой предмет залога в течение месяца со дня объявления повторных торгов несостоявшимися, договор залога прекращается.\n\n7. Положения настоящего Кодекса о заключении договора на торгах применяются при реализации заложенного имущества с торгов, если иное не установлено настоящей статьей.","article_title":"Статья 350.2. Порядок проведения торгов при реализации заложенного имущества, не относящегося к недвижимым вещам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35a856dc473bde887f5836125df84b06969552279477ed30b1ed9cbc42f9dc17"},{"code_id":"GK_RF","article_number":"351","version_date":"1994-11-30","article_text":"1. Залогодержатель вправе потребовать досрочного исполнения обеспеченного залогом обязательства в случаях:\n\n1) выбытия предмета залога, оставленного у залогодателя, из его владения не в соответствии с условиями договора залога;\n\n2) гибели или утраты предмета залога по обстоятельствам, за которые залогодержатель не отвечает, если залогодатель не воспользовался правом, предусмотренным пунктом 2 статьи 345 настоящего Кодекса;\n\n3) иных случаях, предусмотренных законом или договором.\n\n2. Поскольку иное не предусмотрено договором, залогодержатель вправе потребовать досрочного исполнения обеспеченного залогом обязательства или, если его требование не будет удовлетворено, обратить взыскание на предмет залога в случаях:\n\n1) нарушения залогодателем правил о последующем залоге (статья 342);\n\n2) невыполнения залогодателем обязанностей, предусмотренных подпунктами 1 и 3 пункта 1 и пунктом 2 статьи 343 настоящего Кодекса;\n\n3) нарушения залогодателем правил об отчуждении заложенного имущества или о предоставлении его во временное владение или пользование третьим лицам (пункты 2 и 4 статьи 346);\n\n4) иных случаях, предусмотренных законом.","article_title":"Статья 351. Досрочное исполнение обязательства, обеспеченного залогом, и обращение взыскания на заложенное имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f74546abd8c256403cc85364cd772c299d07725907bd0c01a94ab85dbb0ef5d0"},{"code_id":"GK_RF","article_number":"352","version_date":"1994-11-30","article_text":"1. Залог прекращается:\n\n1) с прекращением обеспеченного залогом обязательства;\n\n2) если заложенное имущество возмездно приобретено лицом, которое не знало и не должно было знать, что это имущество является предметом залога;\n\n3) в случае гибели заложенной вещи или прекращения заложенного права, если залогодатель не воспользовался правом, предусмотренным пунктом 2 статьи 345 настоящего Кодекса;\n\n4) в случае реализации заложенного имущества в целях удовлетворения требований залогодержателя в порядке, установленном законом, в том числе при оставлении залогодержателем заложенного имущества за собой, и в случае, если он не воспользовался этим правом (пункт 5 статьи 3502);\n\n5) в случае прекращения договора залога в порядке и по основаниям, которые предусмотрены законом, а также в случае признания договора залога недействительным;\n\n6) по решению суда в случае, предусмотренном пунктом 3 статьи 343 настоящего Кодекса;\n\n7) в случае изъятия заложенного имущества (статьи 167, 327), за исключением случаев, предусмотренных пунктом 1 статьи 353 настоящего Кодекса;\n\n8) в случае реализации заложенного имущества в целях удовлетворения требований предшествующего залогодержателя (пункт 3 статьи 3421);\n\n9) в случаях, указанных в пункте 2 статьи 354 и статье 355 настоящего Кодекса;\n\n10) в иных случаях, предусмотренных законом или договором.\n\n2. При прекращении залога залогодержатель, у которого находилось заложенное имущество, обязан возвратить его залогодателю или иному управомоченному лицу.\n\nЗалогодатель вправе требовать от залогодержателя совершения всех необходимых действий, направленных на внесение записи о прекращении залога (статья 3391).","article_title":"Статья 352. Прекращение залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7bfc85feda8effc870e5643042e2ec92eff1fb552de3a103aa5eef9adba53d5f"},{"code_id":"GK_RF","article_number":"353","version_date":"1994-11-30","article_text":"1. В случае перехода прав на заложенное имущество от залогодателя к другому лицу в результате возмездного или безвозмездного отчуждения этого имущества (за исключением случаев, указанных в подпункте 2 пункта 1 статьи 352 и статье 357 настоящего Кодекса) либо в порядке универсального правопреемства залог сохраняется.\n\nПравопреемник залогодателя приобретает права и несет обязанности залогодателя, за исключением прав и обязанностей, которые в силу закона или существа отношений между сторонами связаны с первоначальным залогодателем.\n\n2. Если имущество залогодателя, являющееся предметом залога, перешло в порядке правопреемства к нескольким лицам, каждый из правопреемников (приобретателей имущества) несет вытекающие из залога последствия неисполнения обеспеченного залогом обязательства соразмерно перешедшей к нему части указанного имущества. Однако если предмет залога неделим или по иным основаниям остается в общей собственности правопреемников, они становятся солидарными залогодателями.","article_title":"Статья 353. Сохранение залога при переходе прав на заложенное имущество к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e2373f4b0345f96b7ccac0fc5ba91471c7dd8e475e56026029ea7c46b39ad95"},{"code_id":"GK_RF","article_number":"354","version_date":"1994-11-30","article_text":"1. Залогодержатель без согласия залогодателя вправе передать свои права и обязанности по договору залога другому лицу с соблюдением правил, установленных главой 24 настоящего Кодекса.\n\n2. Передача залогодержателем своих прав и обязанностей по договору залога другому лицу допускается при условии одновременной уступки тому же лицу права требования к должнику по основному обязательству, обеспеченному залогом. Если иное не предусмотрено законом, при несоблюдении указанного условия залог прекращается.","article_title":"Статья 354. Передача прав и обязанностей по договору залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f85eba2fba673cb3dc64a4f14590aa62a1e8ff9dee2ee37fd72d3940de136da"},{"code_id":"GK_RF","article_number":"355","version_date":"1994-11-30","article_text":"С переводом на другое лицо долга по обязательству, обеспеченному залогом, залог прекращается, если иное не предусмотрено соглашением между кредитором и залогодателем.","article_title":"Статья 355. Перевод долга по обязательству, обеспеченному залогом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26a10f210df59cb40d861fcfec6113ab1c871227fef12e4c00f0bd52eeb73d20"},{"code_id":"GK_RF","article_number":"356","version_date":"1994-11-30","article_text":"1. Кредитор (кредиторы) по обеспечиваемому залогом обязательству (обязательствам), исполнение которого связано с осуществлением его сторонами предпринимательской деятельности, вправе заключить договор управления залогом с одним из таких кредиторов или третьим лицом (управляющим залогом).\n\nПо договору управления залогом управляющий залогом, действуя от имени и в интересах всех кредиторов, заключивших договор, обязуется заключить договор залога с залогодателем и (или) осуществлять все права и обязанности залогодержателя по договору залога, а кредитор (кредиторы) - компенсировать управляющему залогом понесенные им расходы и уплатить ему вознаграждение, если иное не предусмотрено договором.\n\nЕсли залог возник ранее заключения договора управления залогом, управляющий залогом по соглашению о передаче договора залога (статья 3923) вправе осуществлять в силу договора управления залогом все права и обязанности залогодержателя.\n\nКредитор (кредиторы) не вправе осуществлять свои права и обязанности залогодержателей до момента прекращения договора управления залогом.\n\nПереход прав кредитора по обеспечиваемому залогом обязательству к другому лицу влечет перемену соответствующего лица в отношениях по договору управления залогом, если иное не предусмотрено законом или договором либо не вытекает из существа обязательства. Договор управления залогом может предусматривать заранее данное согласие управляющего залогом на замену стороны в таком договоре в случае уступки прав по обеспечиваемому залогом обязательству. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\n2. Управляющим залогом может быть индивидуальный предприниматель или коммерческая организация.\n\n3. Управляющий залогом обязан осуществлять все права и обязанности залогодержателя по договору залога на наиболее выгодных для кредитора (кредиторов) условиях. Полномочия управляющего залогом определяются договором управления залогом (пункт 4 статьи 185) и могут быть изменены по соглашению сторон договора управления залогом.\n\nДоговором управления залогом может быть предусмотрено, что определенные правомочия залогодержателя осуществляются управляющим залогом с предварительного согласия кредитора (кредиторов).\n\n4. Имущество, полученное управляющим залогом в интересах кредиторов, являющихся сторонами договора управления залогом, в том числе в результате обращения взыскания на предмет залога, поступает в долевую собственность указанных кредиторов пропорционально размерам их требований, обеспеченных залогом, если иное не установлено соглашением между кредиторами, и подлежит продаже по требованию любого из кредиторов.\n\nУправляющий залогом обязан вести реестр всех кредиторов, являющихся сторонами договора управления залогом, и оснований возникновения их требований. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\nЕсли иное не предусмотрено договором управления залогом, денежные средства, получаемые управляющим залогом в результате исполнения договора управления залогом, подлежат зачислению на номинальный счет, который обязан открыть управляющий залогом и бенефициаром (бенефициарами) по которому является кредитор (кредиторы). (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\nВ случае заключения договора синдицированного кредита (займа), обеспеченного залогом, бенефициаром (бенефициарами) по договору номинального счета, указанного в абзаце третьем настоящего пункта, является кредитор (кредиторы), при этом управляющий залогом обязан перечислить денежные средства, поступившие на номинальный счет управляющего залогом, на счет кредитного управляющего в срок, определяемый договором управления залогом. Иной порядок передачи кредитору (кредиторам) причитающихся ему в результате исполнения договора управления залогом денежных средств может быть предусмотрен договором управления залогом. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\n5. Договор управления залогом прекращается вследствие:\n\n1) прекращения обеспеченного залогом обязательства;\n\n2) расторжения договора по решению кредитора (кредиторов) в одностороннем порядке;\n\n3) признания управляющего залогом несостоятельным (банкротом).\n\n6. В части, не урегулированной настоящей статьей, если иное не вытекает из существа обязательств сторон, к обязанностям управляющего по договору управления залогом, не являющегося залогодержателем, применяются правила о договоре поручения, а к правам и обязанностям залогодержателей по отношению друг к другу применяются правила о договоре простого товарищества, заключаемом для осуществления предпринимательской деятельности.\n\n2. Отдельные виды залога","article_title":"Статья 356. Договор управления залогом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0097fbed5c50ec23461b19ae7486e0fad1e9534167fa310b0ea84634d3db8382"},{"code_id":"GK_RF","article_number":"357","version_date":"1994-11-30","article_text":"1. Залогом товаров в обороте признается залог товаров с оставлением их у залогодателя и с предоставлением залогодателю права изменять состав и натуральную форму заложенного имущества (товарных запасов, сырья, материалов, полуфабрикатов, готовой продукции и т.п.) при условии, что их общая стоимость не становится меньше указанной в договоре залога.\n\nПредмет залога по договору залога товаров в обороте может быть определен посредством указания родовых признаков соответствующих товаров и мест их нахождения в определенных зданиях, помещениях или на земельных участках.\n\nУменьшение стоимости заложенных товаров в обороте допускается соразмерно исполненной части обеспеченного залогом обязательства, если иное не предусмотрено договором.\n\n2. Товары в обороте, отчужденные залогодателем, перестают быть предметом залога с момента их перехода в собственность, хозяйственное ведение или оперативное управление приобретателя, а приобретенные залогодателем товары, которые указаны в договоре залога товаров в обороте, становятся предметом залога с момента возникновения у залогодателя на них права собственности, хозяйственного ведения или оперативного управления.\n\n3. Залогодатель товаров в обороте обязан вести книгу записи залогов, в которую вносятся записи об условиях залога товаров и обо всех операциях, влекущих изменение состава или натуральной формы заложенных товаров, включая их переработку, на день последней операции, если иное не предусмотрено договором залога.\n\n4. При нарушении залогодателем условий залога товаров в обороте залогодержатель вправе приостановить операции с заложенными товарами до устранения нарушения путем наложения на них своих знаков и печатей. В целях различения указанных заложенных товаров и иных вещей может быть нотариально удостоверен факт нахождения заложенных товаров в определенном месте в определенное время.","article_title":"Статья 357. Залог товаров в обороте","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e6851649eb59383f0e0db3153abf30573e49cac42eb1bbd35e8b0d02fcbc770"},{"code_id":"GK_RF","article_number":"358","version_date":"1994-11-30","article_text":"1. Принятие от граждан в залог движимых вещей, предназначенных для личного потребления, в обеспечение краткосрочных займов может осуществляться в качестве предпринимательской деятельности специализированными организациями - ломбардами.\n\n2. Договор займа оформляется выдачей ломбардом залогового билета.\n\n3. Закладываемые вещи передаются в ломбард.\n\nЛомбард обязан страховать в пользу залогодателя за свой счет принятые в залог вещи в полной сумме их оценки, соответствующей ценам на вещи такого рода и такого качества, обычно устанавливаемым в торговле в момент их принятия в залог.\n\nЛомбард не вправе пользоваться и распоряжаться заложенными вещами.\n\n4. Ломбард несет ответственность за утрату з\n\nаложенных вещей и их повреждение, если не докажет, что утрата, повреждение произошли вследствие непреодолимой силы.\n\n5. В случае невозвращения в установленный срок суммы займа, обеспеченного залогом вещей в ломбарде, ломбард по истечении льготного месячного срока вправе продать это имущество в порядке, установленном законом о ломбардах. После этого требования ломбарда к залогодателю (должнику) погашаются, даже если сумма, вырученная при реализации заложенного имущества, недостаточна для их полного удовлетворения.\n\n6. Правила кредитования граждан ломбардами под залог принадлежащих гражданам вещей устанавливаются законом о ломбардах в соответствии с настоящим Кодексом.\n\n7. Условия договора займа, ограничивающие права залогодателя по сравнению с правами, предоставляемыми ему настоящим Кодексом и другими законами, ничтожны. Вместо таких условий применяются соответствующие положения закона.","article_title":"Статья 358. Залог вещей в ломбарде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f93d1dd00fde57feeb2f9373cae6db4f4deaa1161147e6843b67458d5cdac751"},{"code_id":"GK_RF","article_number":"358.1","version_date":"1994-11-30","article_text":"1. Предметом залога могут быть имущественные права (требования), вытекающие из обязательства залогодателя. Залогодателем права может быть лицо, являющееся кредитором в обязательстве, из которого вытекает закладываемое право (правообладатель).\n\nЕсли законом или договором залога права не установлено иное, предметом залога являются все принадлежащие залогодателю права, которые вытекают из соответствующего обязательства и могут быть предметом залога.\n\n2. Предметом залога может быть право, которое возникнет в будущем из существующего или будущего обязательства.\n\n3. Если иное не установлено законом или договором либо не следует из существа обязательства, предметом залога могут быть часть требования, отдельное требование или несколько требований, вытекающих из договора или иного обязательства.\n\n4. Предметом залога по одному договору залога может быть совокупность прав (требований), каждое из которых вытекает из самостоятельного обязательства, в том числе совокупность будущих прав, а также совокупность существующих и будущих прав.\n\n5. Если заложенное право прекратилось в связи с окончанием срока его действия до обращения на него взыскания залогодержателем, залогодержатель не вправе требовать досрочного исполнения основного обязательства, исполнение которого было обеспечено залогом этого права.\n\n6. В случаях, установленных законом или договором, при обращении взыскания на заложенное право и реализации заложенного права к его приобретателю вместе с этим правом переходят связанные с ним обязанности.","article_title":"Статья 358.1. Залог обязательственных прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d1f9ff235e479508f16fed6a930e0bb856e55fb3837fba665f9ee4cd71ff65e"},{"code_id":"GK_RF","article_number":"358.10","version_date":"1994-11-30","article_text":"1. В договоре залога прав по договору банковского счета должны быть указаны банковские реквизиты залогового счета, существо, размер и срок исполнения обязательства, обеспечиваемого залогом прав по договору банковского счета.\n\n2. Если иное не предусмотрено договором залога прав по договору банковского счета, договор считается заключенным с условием о залоге прав в отношении всей денежной суммы, находящейся на залоговом счете в любой момент в течение времени действия договора.\n\n3. Договором залога прав по договору банковского счета может быть предусмотрено, что предметом залога являются права залогодателя по договору банковского счета в отношении твердой денежной суммы, размер которой указан в договоре залога. В этом случае размер денежных средств на счете залогодателя в любой момент в течение времени действия договора залога не должен быть ниже определенной договором суммы.\n\nЕсли иное не предусмотрено договором залога, уменьшение размера твердой денежной суммы, в отношении которой заложены права залогодателя по договору банковского счета, соразмерно исполненной части обеспеченного залогом обязательства не допускается.","article_title":"Статья 358.10. Содержание договора залога прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a9a6b70671404122d90c0eee9597ca13f685825098caf68c0b531648397e363"},{"code_id":"GK_RF","article_number":"358.11","version_date":"1994-11-30","article_text":"Залог на основании договора залога прав по договору банковского счета возникает с момента уведомления банка о залоге прав и предоставления ему копии договора залога. В случае, если залогодержателем является банк, заключивший с клиентом (залогодателем) договор залогового счета, залог возникает с момента заключения договора залога прав по банковскому счету.","article_title":"Статья 358.11. Возникновение залога прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bf68a39ee31902bfc75129cecb3fd614958f8aae63aa400aa1b49f42194dd86"},{"code_id":"GK_RF","article_number":"358.12","version_date":"1994-11-30","article_text":"1. Залогодатель вправе распоряжаться свободно денежными средствами на залоговом счете, если иное не предусмотрено договором залога прав по соответствующему договору банковского счета или правилами настоящей статьи.\n\nБанк обязан проводить операции по залоговому счету в соответствии с правилами настоящего параграфа и иными правилами настоящего Кодекса, другими законами и банковскими правилами, а в части, ими не урегулированной, в соответствии с соглашением, заключенным между банком, залогодателем и залогодержателем.\n\n2. Банк по требованию залогодержателя, предъявленному в письменной форме, обязан предоставлять ему сведения об остатке денежных средств на залоговом счете, об операциях по указанному счету и о предъявленных по счету требованиях, а также о запретах и об ограничениях, наложенных на указанный счет. Порядок и сроки предоставления банком таких сведений залогодержателю определяются банковскими правилами, а в части, ими не урегулированной, соглашением, заключенным между банком, залогодателем и залогодержателем.\n\n3. При заключении договора залога прав залогодателя по договору банковского счета в отношении твердой денежной суммы залогодатель без согласия в письменной форме залогодержателя не вправе давать банку распоряжения, в результате исполнения которых сумма денежных средств на залоговом счете станет ниже указанной твердой денежной суммы, а банк не вправе исполнять такие распоряжения.\n\n4. После получения банком уведомления в письменной форме залогодержателя о неисполнении или ненадлежащем исполнении должником обеспеченного залогом обязательства банк не вправе исполнять распоряжения залогодателя, в результате исполнения которых сумма денежных средств на залоговом счете станет ниже суммы, эквивалентной размеру обеспеченного обязательства, указанному в договоре залога.\n\n5. Банк, нарушивший обязанности, указанные в пунктах 3 и 4 настоящей статьи, несет перед залогодержателем в пределах денежных сумм, списанных с залогового счета во исполнение распоряжения клиента (залогодателя), солидарную с ним ответственность.","article_title":"Статья 358.12. Распоряжение банковским счетом, права по которому заложены","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97936d2188dba24dfc1bf20f8d46abf6be879070c9b6430b4c09170744022741"},{"code_id":"GK_RF","article_number":"358.13","version_date":"1994-11-30","article_text":"Без согласия залогодержателя стороны договора банковского счета, права по которому заложены, не вправе вносить в него изменения, а также совершать действия, влекущие прекращение такого договора.","article_title":"Статья 358.13. Изменение и прекращение договора залога прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6964cf87c02a4760c95067bfe4056330e958c5ec6ed87573a7aab0ea28ccce3"},{"code_id":"GK_RF","article_number":"358.14","version_date":"1994-11-30","article_text":"1. При обращении взыскания на заложенные права по договору банковского счета в соответствии со статьей 349 настоящего Кодекса в судебном или во внесудебном порядке требования залогодержателя удовлетворяются путем списания банком на основании распоряжения залогодержателя денежных средств с залогового счета залогодателя и выдачи их залогодержателю или зачисления их на счет, указанный залогодержателем (пункт 2 статьи 854). Правила о реализации заложенного имущества, установленные статьями 350 - 3502 настоящего Кодекса, в этих случаях не применяются.","article_title":"Статья 358.14. Реализация заложенных прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33c1f5aca2b99572968ec4c0c69087150b49e197970eceedd9a2be02b2c87092"},{"code_id":"GK_RF","article_number":"358.15","version_date":"1994-11-30","article_text":"1. Залог прав акционера осуществляется посредством залога принадлежащих акционеру акций этого общества, залог прав участника общества с ограниченной ответственностью - посредством залога принадлежащей ему доли в уставном капитале общества в соответствии с правилами, установленными настоящим Кодексом и законами о хозяйственных обществах.\n\nЗалог прав участников (учредителей) иных юридических лиц не допускается.\n\n2. При залоге акций удостоверенные ими права осуществляет залогодатель (акционер), если иное не предусмотрено договором залога акций (статья 35817).\n\nЕсли иное не предусмотрено договором залога доли в уставном капитале общества с ограниченной ответственностью, до момента прекращения залога права участника общества осуществляются залогодержателем.","article_title":"Статья 358.15. Залог прав участников юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37efdc4ad964bacf06e183cf0f63c439ee642fb7980931fdfd8fc43871723fd8"},{"code_id":"GK_RF","article_number":"358.16","version_date":"1994-11-30","article_text":"1. Залог документарной ценной бумаги возникает с момента передачи ее залогодержателю, если иное не установлено законом или договором.\n\nЗалог бездокументарной ценной бумаги возникает с момента внесения записи о залоге по счету, на котором учитываются права владельца бездокументарных ценных бумаг, или в случаях, установленных законом, по счету иного лица, если законом или договором не установлено, что залог возникает позднее.\n\n2. Если залог ордерной ценной бумаги совершен посредством залогового индоссамента, правоотношения между залогодателем, залогодержателем и должником по ордерной ценной бумаге регулируются законами о ценных бумагах.\n\n3. К отношениям, связанным с залогом документарных ценных бумаг и не урегулированным настоящей статьей, статьей 35817 настоящего Кодекса или другими законами, применяются правила о залоге вещей, если иное не установлено законами о ценных бумагах и не вытекает из существа соответствующих ценных бумаг.\n\n4. К отношениям, связанным с залогом бездокументарных ценных бумаг и не урегулированным настоящей статьей, статьей 35817 настоящего Кодекса или другими законами, применяются правила о залоге документарных бумаг, если иное не вытекает из существа соответствующих бездокументарных ценных бумаг.","article_title":"Статья 358.16. Залог ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ac84d882716230c633456f85d5dfa78bed6b6321b30d79d4a9b606801662a35"},{"code_id":"GK_RF","article_number":"358.17","version_date":"1994-11-30","article_text":"Если договором залога залогодержатель ограничен в осуществлении прав, удостоверенных ценной бумагой, нарушение им таких ограничений не затрагивает права и обязанности третьих лиц, которые не знали и не должны были знать о таких ограничениях. Однако залогодержатель несет перед залогодателем ответственность за данные нарушения, предусмотренную законом и договором, а залогодатель вправе требовать в судебном порядке прекращения права залога.\n\nудостоверенных заложенной ценной бумагой, в случае нарушения залогодателем указанной обязанности он несет перед залогодержателем ответственность, предусмотренную законом и договором, а залогодержатель вправе требовать досрочного исполнения обеспеченного залогом обязательства.\n\nЕсли в соответствии с законом залогодатель ценных бумаг в силу того, что он является их владельцем, дополнительно к ним безвозмездно получает иные ценные бумаги или иное имущество, такие ценные бумаги или такое имущество находятся в залоге у залогодержателя (пункт 3 статьи 336).","article_title":"Статья 358.17. Осуществление прав, удостоверенных заложенной ценной бумагой","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51b1ea01383fd16a65d48669b29f19df6c6adbb1c08c24dc7f76186aa163b534"},{"code_id":"GK_RF","article_number":"358.18","version_date":"1994-11-30","article_text":"1. Исключительные права на результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий (пункт 1 статьи 1225) могут быть предметом залога в той мере, в какой правила настоящего Кодекса допускают их отчуждение.\n\n2. Государственная регистрация залога исключительных прав осуществляется в соответствии с правилами раздела VII настоящего Кодекса.\n\n3. К договору залога исключительного права на результат интеллектуальной деятельности или на средство индивидуализации применяются общие положения о залоге (статьи 334 - 356), а к договору залога прав по договору об отчуждении исключительных прав и по лицензионному (сублицензионному) договору применяются положения о залоге обязательственных прав (статьи 3581 - 3588), поскольку иное не установлено настоящим Кодексом и не вытекает из содержания или характера соответствующих прав.\n\n4. По договору залога исключительного права на результат интеллектуальной деятельности или на средство индивидуализации залогодатель в течение срока действия этого договора без согласия залогодержателя вправе использовать такой результат интеллектуальной деятельности или такое средство индивидуализации и распоряжаться исключительным правом на такой результат или на такое средство, за исключением случая отчуждения исключительного права, если договором не предусмотрено иное. Залогодатель не вправе отчуждать исключительное право без согласия залогодержателя, если иное не предусмотрено договором.\n\n(Дополнение статьей - Федеральный закон от 12.03.2014 № 35-ФЗ)\n\n(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 358.18. Залог исключительных прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"486b7988fdd6d59e5f2a2d380f4c21a7135700f93327de37e0fd55ca0926fb9a"},{"code_id":"GK_RF","article_number":"358.2","version_date":"1994-11-30","article_text":"1. Залог права не требует согласия должника правообладателя, за исключением случаев, предусмотренных законом или соглашением между правообладателем и его должником.\n\n2. В случаях, когда соглашением между правообладателем и его должником уступка права запрещена или невозможность уступки права вытекает из существа обязательства, залог права не допускается, если законом не установлено иное.\n\n3. Залог права допускается только с согласия должника правообладателя в случаях, если:\n\n1) в силу закона или соглашения между правообладателем и его должником для уступки права (требования) необходимо согласие должника;\n\n2) при обращении взыскания на заложенное право и его реализации к приобретателю права должны перейти связанные с заложенным правом обязанности (пункт 6 статьи 3581).\n\n4. Если иное не предусмотрено законом, нарушение правообладателем указанного в договоре с должником, связанном с осуществлением его сторонами предпринимательской деятельности, ограничения по уступке или залогу права (требования) влечет последствия, предусмотренные пунктом 3 статьи 388 настоящего Кодекса.","article_title":"Статья 358.2. Ограничения залога права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18ac8b1a5d38a162dbf51ef83bbc4ab57fee0d9908d6272484427f09abb972ea"},{"code_id":"GK_RF","article_number":"358.3","version_date":"1994-11-30","article_text":"1. В договоре залога права наряду с условиями, предусмотренными статьей 339 настоящего Кодекса, должны быть указаны обязательство, из которого вытекает закладываемое право, сведения о должнике залогодателя и сторона договора залога, у которой находятся подлинники документов, удостоверяющих закладываемое право.\n\nВ случае, если предметом залога является принадлежащее залогодателю право требовать уплаты денежной суммы, в договоре залога может быть указан размер этой суммы или порядок ее определения.\n\nЕсли в договоре залога не указано, что подлинники документов, удостоверяющих закладываемое право, остаются у залогодателя или передаются нотариусу на хранение, залогодатель обязан передать такие подлинники в срок, указанный в договоре залога, или, если договором указанный срок не установлен, в разумный срок залогодержателю по его требованию, предъявленному в письменной форме. Соглашением между залогодателем и залогодержателем может быть предусмотрено, что документы передаются на хранение третьему лицу.\n\nПри залоге права, если иное не предусмотрено законом или договором, обязанности, предусмотренные статьей 343 настоящего Кодекса, возлагаются на сторону договора залога, у которой находятся подлинники документов, удостоверяющих заложенное право.\n\n2. В случаях, если предметом залога является совокупность прав (требований) или будущее право (пункты 2 и 4 статьи 3581), сведения об обязательстве, из которого вытекает закладываемое право, и о должнике залогодателя могут быть указаны в договоре общим образом, то есть посредством данных, позволяющих индивидуализировать закладываемые права и определить лиц, которые являются или на момент обращения взыскания на предмет залога будут являться должниками по этим правам.","article_title":"Статья 358.3. Содержание договора залога права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"634b90f5e1719157add6dde62a7a98815bf6182e97625b5a02bfb0ae6f266e50"},{"code_id":"GK_RF","article_number":"358.4","version_date":"1994-11-30","article_text":"В случае залога прав уведомление должника по обязательству, права по которому закладываются, осуществляется по правилам статьи 385 настоящего Кодекса.","article_title":"Статья 358.4. Уведомление должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18254405fc78adc2c3609b1c08f6044cab2cec0e1aa7330bddf75402058367f6"},{"code_id":"GK_RF","article_number":"358.5","version_date":"1994-11-30","article_text":"1. Залог права возникает с момента заключения договора залога, а при залоге будущего права с момента возникновения этого права.\n\n2. Если залогом права обеспечено исполнение обязательства, которое возникнет в будущем, залог права возникает с момента возникновения этого обязательства.","article_title":"Статья 358.5. Возникновение залога права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6cb32fab38842138e1ecfdda4d96bf47c343da69e15941eb8ec79c9490a7a4f6"},{"code_id":"GK_RF","article_number":"358.6","version_date":"1994-11-30","article_text":"1. Должник залогодателя, право требования к которому заложено, исполняет соответствующее обязательство залогодателю, если договором залога не предусмотрено иное.\n\nЕсли договором залога предусмотрено право залогодержателя получить исполнение от должника по обязательству, право по которому заложено, должник, уведомленный об этом (статья 3584), обязан исполнять свое обязательство залогодержателю или указанному им лицу.\n\n2. Если иное не установлено договором залога, при получении от своего должника в счет исполнения обязательства денежных сумм залогодатель по требованию залогодержателя обязан уплатить ему соответствующие суммы в счет исполнения обязательства, обеспеченного залогом.\n\nЕсли иное не предусмотрено договором залога, денежные суммы, полученные залогодержателем от должника залогодателя по заложенному праву (требованию), засчитываются в погашение обязательства, в обеспечение исполнения которого заложено соответствующее право.\n\n3. После возникновения оснований для обращения взыскания на заложенное право требования залогодержатель имеет право на получение исполнения по данному требованию в пределах, необходимых для покрытия требований залогодержателя, обеспеченных залогом, в том числе право на подачу заявлений об исполнении обязательств до востребования, если предметом залога является требование по обязательству до востребования.\n\n4. Законом или договором залога права может быть предусмотрено, что денежные суммы, полученные залогодателем от его должника в счет исполнения обязательства, право (требование) по которому заложено, зачисляются на залоговый счет залогодателя. К такому счету применяются правила о договоре залога прав по договору банковского счета.","article_title":"Статья 358.6. Исполнение обязательства должником залогодателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"498d3f99f7f5854aa0427ab849bbf65dace7d5085fc490fbe1cb29a2fb62bd46"},{"code_id":"GK_RF","article_number":"358.7","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором, в случае нарушения обязанностей, предусмотренных статьей 3586 настоящего Кодекса, залогодержатель вправе требовать от залогодателя досрочного исполнения обеспеченного залогом обязательства, а при его неисполнении - обратить взыскание на предмет залога в установленном порядке.\n\n2. Залогодержатель вправе принимать самостоятельно меры, необходимые для защиты заложенного права от нарушений со стороны третьих лиц.","article_title":"Статья 358.7. Защита залогодержателя права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61aa8e5a73eda37cfcc8aae9348af06a83bc0dd2384c2a1b29ee58ccbf923f9e"},{"code_id":"GK_RF","article_number":"358.8","version_date":"1994-11-30","article_text":"1. Реализация заложенного права осуществляется в порядке, установленном пунктом 1 статьи 350 и пунктом 1 статьи 3501 настоящего Кодекса.\n\n2. В случае обращения взыскания на заложенное право в судебном порядке стороны могут договориться о том, что его реализация осуществляется посредством перевода по требованию залогодержателя заложенного права на залогодержателя по решению суда.\n\n3. Если взыскание на заложенное право обращается во внесудебном порядке, стороны могут договориться, что реализация заложенного права осуществляется посредством уступки заложенного права залогодателем залогодержателю или указанному залогодержателем третьему лицу. В случае отказа залогодателя уступить заложенное право залогодержатель или третье лицо вправе требовать перевода на себя этого права по решению суда или на основании исполнительной надписи нотариуса и возмещения убытков, причиненных в связи с отказом уступить это право.\n\n4. С момента перехода заложенного права к залогодержателю или указанному им третьему лицу обязательство, исполнение которого обеспечено залогом этого права, прекращается в размере, эквивалентном стоимости (начальной продажной цене) заложенного права (пункт 7 статьи 349).\n\nПравила настоящего пункта применяются, если соглашением залогодателя с залогодержателем, а также с должником по обязательству, обеспеченному залогом права, когда залогодателем является третье лицо, не предусмотрено иное.","article_title":"Статья 358.8. Порядок реализации заложенного права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cff3cd2944aae4221c35aa6fa17c859710883ce19ae27d7f162adf1f9dd97e45"},{"code_id":"GK_RF","article_number":"358.9","version_date":"1994-11-30","article_text":"1. Предметом залога могут быть права по договору банковского счета при условии открытия банком клиенту залогового счета.\n\n2. Залогодержателем при залоге прав по договору банковского счета может быть, в частности, банк, заключивший с клиентом (залогодателем) договор залогового счета.\n\n3. Залоговый счет может быть открыт банком клиенту независимо от заключения на момент его открытия договора залога прав по договору банковского счета.\n\n4. Договор залога прав по договору банковского счета может быть заключен также при отсутствии на момент его заключения у клиента денежных средств на залоговом счете.\n\n5. Договором залога имущества иного, чем права по договору банковского счета, может быть предусмотрено, что причитающиеся залогодателю денежные суммы (страховое возмещение за утрату или повреждение заложенного имущества, доходы от использования заложенного имущества, денежные суммы, подлежащие уплате залогодателю в счет исполнения обязательства, право (требование) по которому заложено, и т.п.) зачисляются на залоговый счет.\n\n6. Удостоверение обязательства банка по заключенному с клиентом договору об открытии залогового счета выдачей банком ценной бумаги не допускается.\n\n7. Если иное не предусмотрено настоящей статьей и статьями 35810 - 35814 настоящего Кодекса, к договору об открытии залогового счета применяются правила главы 45 настоящего Кодекса.\n\n8. Правила настоящего Кодекса о залоге прав по договору банковского счета (настоящая статья и статьи 35810 - 35814) соответственно применяются к залогу прав по договору банковского вклада.","article_title":"Статья 358.9. Основные положения о залоге прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c44a72f0776f2255b21b7249cf1c094a3223fc253840b85b4cea0546f1a088fc"},{"code_id":"GK_RF","article_number":"359","version_date":"1994-11-30","article_text":"1. Кредитор, у которого находится вещь, подлежащая передаче должнику либо лицу, указанному должником, вправе в случае неисполнения должником в срок обязательства по оплате этой вещи или возмещению кредитору связанных с нею издержек и других убытков удерживать ее до тех пор, пока соответствующее обязательство не будет исполнено.\n\nУдержанием вещи могут обеспечиваться также требования, хотя и не связанные с оплатой вещи или возмещением издержек на нее и других убытков, но возникшие из обязательства, стороны которого действуют как предприниматели.\n\n2. Кредитор может удерживать находящуюся у него вещь, несмотря на то, что после того, как эта вещь поступила во владение кредитора, права на нее приобретены третьим лицом.\n\n3. Правила настоящей статьи применяются, если договором не предусмотрено иное.","article_title":"Статья 359. Основания удержания","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1da7a5102b316d77e12366596a47cdbd99eb48cc163342ea322069da2a8bc67"},{"code_id":"GK_RF","article_number":"36","version_date":"1994-11-30","article_text":"1. Обязанности по опеке и попечительству исполняются безвозмездно, кроме случаев, предусмотренных законом.\n\n2. Опекуны и попечители несовершеннолетних граждан обязаны проживать совместно со своими подопечными. Раздельное проживание попечителя с подопечным, достигшим шестнадцати лет, допускается с разрешения органа опеки и попечительства при условии, что это не отразится неблагоприятно на воспитании и защите прав и интересов подопечного.\n\nОпекуны и попечители обязаны извещать органы опеки и попечительства о перемене места жительства.\n\n3. Опекуны и попечители обязаны заботиться о содержании своих подопечных, об обеспечении их уходом и лечением, защищать их права и интересы.\n\nОпекуны и попечители несовершеннолетних должны заботиться об их обучении и воспитании.\n\nОпекуны и попечители заботятся о развитии (восстановлении) способности гражданина, дееспособность которого ограничена вследствие психического расстройства, или гражданина, признанного недееспособным, понимать значение своих действий или руководить ими. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\nОпекуны и попечители исполняют свои функции, учитывая мнение подопечного, а при невозможности его установления - с учетом информации о предпочтениях подопечного, полученной от его родителей, прежних опекунов, иных лиц, оказывавших ему услуги и добросовестно исполнявших свои обязанности. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\nЕсли основания, в силу которых гражданин, который вследствие психического расстройства может понимать значение своих действий или руководить ими при помощи других лиц, был ограничен в дееспособности, изменились, попечитель обязан обратиться в суд с заявлением об отмене ограничения дееспособности подопечного или о признании его недееспособным в соответствии с пунктом 3 статьи 30 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 36. Исполнение опекунами и попечителями своих обязанностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69b841d0148e7838e3348d0870766a7f38a927eb2b9ae5266e0b6819a74effef"},{"code_id":"GK_RF","article_number":"360","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nТребования кредитора, удерживающего вещь, удовлетворяются из ее стоимости в объеме и порядке, предусмотренных для удовлетворения требований, обеспеченных залогом.","article_title":"Статья 360. Удовлетворение требований за счет удерживаемой вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f317284749664e33cbb4d0efbde050a79470bbc026ff8cf350a739f44eee066"},{"code_id":"GK_RF","article_number":"361","version_date":"1994-11-30","article_text":"1. По договору поручительства поручитель обязывается перед кредитором другого лица отвечать за исполнение последним его обязательства полностью или в части. Договор поручительства может быть заключен в обеспечение как денежных, так и неденежных обязательств, а также в обеспечение обязательства, которое возникнет в будущем.\n\n2. Поручительство может возникать на основании закона при наступлении указанных в нем обстоятельств. Правила настоящего Кодекса о поручительстве в силу договора применяются к поручительству, возникающему на основании закона, если законом не установлено иное.\n\n3. Условия поручительства, относящиеся к основному обязательству, считаются согласованными, если в договоре поручительства имеется отсылка к договору, из которого возникло или возникнет в будущем обеспечиваемое обязательство. В договоре поручительства, поручителем по которому является лицо, осуществляющее предпринимательскую деятельность, может быть указано, что поручительство обеспечивает все существующие и (или) будущие обязательства должника перед кредитором в пределах определенной суммы.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 361. Основания возникновения поручительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a7ea752f5a82de7d2f348c418de8249f01ea8f20fca9f3a680582fb3f2fbf91"},{"code_id":"GK_RF","article_number":"362","version_date":"1994-11-30","article_text":"Договор поручительства должен быть совершен в письменной форме. Несоблюдение письменной формы влечет недействительность договора поручительства.","article_title":"Статья 362. Форма договора поручительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad47a42d6be1ef1196c3711e4e7c7885efe481e89411fe1664cd9fbdc8c15985"},{"code_id":"GK_RF","article_number":"363","version_date":"1994-11-30","article_text":"1. При неисполнении или ненадлежащем исполнении должником обеспеченного поручительством обязательства поручитель и должник отвечают перед кредитором солидарно, если законом или договором поручительства не предусмотрена субсидиарная ответственность поручителя.\n\n2. Поручитель отвечает перед кредитором в том же объеме, как и должник, включая уплату процентов, возмещение судебных издержек по взысканию долга и других убытков кредитора, вызванных неисполнением или ненадлежащим исполнением обязательства должником, если иное не предусмотрено договором поручительства.","article_title":"Статья 363. Ответственность поручителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3547976595ed13e9580ddfcea132fdd94a1810237774234b811ee1aa2f85f5e7"},{"code_id":"GK_RF","article_number":"365","version_date":"1994-11-30","article_text":"1. К поручителю, исполнившему обязательство, переходят права кредитора по этому обязательству и права, принадлежавшие кредитору как залогодержателю, в том объеме, в котором поручитель удовлетворил требование кредитора. Поручитель также вправе требовать от должника уплаты процентов на сумму, выплаченную кредитору, и возмещения иных убытков, понесенных в связи с ответственностью за должника.\n\n2. По исполнении поручителем обязательства кредитор обязан вручить поручителю документы, удостоверяющие требование к должнику, и передать права, обеспечивающие это требование.\n\n3. Правила, установленные настоящей статьей, применяются, если иное не предусмотрено законом, иными правовыми актами или договором поручителя с должником и не вытекает из отношений между ними.","article_title":"Статья 365. Права поручителя, исполнившего обязательство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"297acfe64095c5f56baa8a9d55a04255d2dd48521b3d2fdaa30bf45d049e76be"},{"code_id":"GK_RF","article_number":"366","version_date":"1994-11-30","article_text":"1. Должник, извещенный поручителем о предъявленном к нему кредитором требовании или привлеченный поручителем к участию в деле, обязан сообщить поручителю обо всех имеющихся у него возражениях против этого требования и предоставить имеющиеся у него в подтверждение этих требований доказательства. В противном случае должник лишается права выдвигать возражения, которые могли быть заявлены против требования кредитора, против требования поручителя (пункт 1 статьи 365), если иное не предусмотрено соглашением между поручителем и должником.\n\n2. Должник, исполнивший обязательство, обеспеченное поручительством, обязан известить об этом поручителя немедленно. В противном случае поручитель, в свою очередь исполнивший свое обязательство, вправе взыскать с кредитора неосновательно полученное или предъявить регрессное требование к должнику. В последнем случае должник вправе взыскать с кредитора лишь неосновательно полученное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 366. Извещения при поручительстве","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b20b35c5ae604f228f29655b15d0ff15ed4db02da5d7ec3059dc1339e90f1c27"},{"code_id":"GK_RF","article_number":"367","version_date":"1994-11-30","article_text":"1. Поручительство прекращается с прекращением обеспеченного им обязательства. Прекращение обеспеченного обязательства в связи с ликвидацией должника после того, как кредитор предъявил в суд или в ином установленном законом порядке требование к поручителю, не прекращает поручительство.\n\nЕсли основное обязательство обеспечено поручительством в части, частичное исполнение основного обязательства засчитывается в счет его необеспеченной части.\n\nЕсли между должником и кредитором существует несколько обязательств, только одно из которых обеспечено поручительством, и должник не указал, какое из обязательств он исполняет, считается, что им исполнено необеспеченное обязательство.\n\n2. В случае, если обеспеченное поручительством обязательство было изменено без согласия поручителя, что повлекло за собой увеличение ответственности или иные неблагоприятные последствия для поручителя, поручитель отвечает на прежних условиях.\n\nДоговор поручительства может предусматривать заранее данное согласие поручителя в случае изменения обязательства отвечать перед кредитором на измененных условиях. Такое согласие должно предусматривать пределы, в которых поручитель согласен отвечать по обязательствам должника.\n\n3. Поручительство прекращается с переводом на другое лицо долга по обеспеченному поручительством обязательству, если поручитель в разумный срок после направления ему уведомления о переводе долга не согласился отвечать за нового должника.\n\nСогласие поручителя отвечать за нового должника должно быть явно выраженным и должно позволять установить круг лиц, при переводе долга на которых поручительство сохраняет силу.\n\n4. Смерть должника, реорганизация юридического лица-должника не прекращают поручительство.\n\n5. Поручительство прекращается, если кредитор отказался принять надлежащее исполнение, предложенное должником или поручителем.\n\n6. Поручительство прекращается по истечении указанного в договоре поручительства срока, на который оно дано. Если такой срок не установлен, оно прекращается при условии, что кредитор в течение года со дня наступления срока исполнения обеспеченного поручительством обязательства не предъявит иск к поручителю. Когда срок исполнения основного обязательства не указан и не может быть определен или определен моментом востребования, поручительство прекращается, если кредитор не предъявит иск к поручителю в течение двух лет со дня заключения договора поручительства.\n\nПредъявление кредитором к должнику требования о досрочном исполнении обязательства не сокращает срок действия поручительства, определяемый исходя из первоначальных условий основного обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 367. Прекращение поручительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"573a08b415364e72d87637edbdbe89deced86035052eefc1ce0796a3b3906de7"},{"code_id":"GK_RF","article_number":"368","version_date":"1994-11-30","article_text":"1. По независимой гарантии гарант принимает на себя по просьбе другого лица (принципала) обязательство уплатить указанному им третьему лицу (бенефициару) определенную денежную сумму в соответствии с условиями данного гарантом обязательства независимо от действительности обеспечиваемого такой гарантией обязательства. Требование об определенной денежной сумме считается соблюденным, если условия независимой гарантии позволяют установить подлежащую выплате денежную сумму на момент исполнения обязательства гарантом.\n\n2. Независимая гарантия выдается в письменной форме (пункт 2 статьи 434), позволяющей достоверно определить условия гарантии и удостовериться в подлинности ее выдачи определенным лицом в порядке, установленном законодательством, обычаями или соглашением гаранта с бенефициаром.\n\n3. Независимые гарантии могут выдаваться банками или иными кредитными организациями (банковские гарантии), а также другими коммерческими организациями.\n\nК обязательствам лиц, не указанных в абзаце первом настоящего пункта и выдавших независимую гарантию, применяются правила о договоре поручительства.\n\n4. В независимой гарантии должны быть указаны:\n\nдата выдачи;\n\nпринципал;\n\nбенефициар;\n\nосновное обязательство, исполнение по которому обеспечивается гарантией;\n\nденежная сумма, подлежащая выплате, или порядок ее определения;\n\nсрок действия гарантии;\n\nобстоятельства, при наступлении которых должна быть выплачена сумма гарантии.\n\nВ независимой гарантии может содержаться условие об уменьшении или увеличении суммы гарантии при наступлении определенного срока или определенного события.\n\n5. Правила настоящего параграфа применяются также в случаях, когда обязательство лица, предоставившего обеспечение, состоит в передаче акций, облигаций или вещей, определенных родовыми признаками, если иное не вытекает из существа отношений.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 368. Понятие и форма независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44c517347282b0704b4075bd986de1a82c58762dc80116727a0579875fbf07c7"},{"code_id":"GK_RF","article_number":"369","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 369. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca90085597fc0f29c91e6a270b419228a61499115e0d30be41e77deb80417b2b"},{"code_id":"GK_RF","article_number":"37","version_date":"1994-11-30","article_text":"Порядок управления имуществом подопечного определяется Федеральным законом \"Об опеке и попечительстве\". (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)","article_title":"Статья 37. Распоряжение имуществом подопечного","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2df459b1ef3f5c0d6d00dcc7057be583e3c7cd7bbaaaf789b5113b9189d7152c"},{"code_id":"GK_RF","article_number":"370","version_date":"1994-11-30","article_text":"1. Предусмотренное независимой гарантией обязательство гаранта перед бенефициаром не зависит в отношениях между ними от основного обязательства, в обеспечение исполнения которого она выдана, от отношений между принципалом и гарантом, а также от каких-либо других обязательств, даже если в независимой гарантии содержатся ссылки на них.\n\n2. Гарант не вправе выдвигать против требования бенефициара возражения, вытекающие из основного обязательства, в обеспечение исполнения которого независимая гарантия выдана, а также из какого-либо иного обязательства, в том числе из соглашения о выдаче независимой гарантии, и в своих возражениях против требования бенефициара об исполнении независимой гарантии не вправе ссылаться на обстоятельства, не указанные в гарантии.\n\n3. Гарант не вправе предъявлять бенефициару к зачету требование, уступленное гаранту принципалом, если иное не предусмотрено независимой гарантией или соглашением гаранта с бенефициаром.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 370. Независимость гарантии от иных обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cef0c236be41a6919b32801afda28206460bc9c330ed5dee749b417f2c9ad708"},{"code_id":"GK_RF","article_number":"371","version_date":"1994-11-30","article_text":"1. Независимая гарантия не может быть отозвана или изменена гарантом, если в ней не предусмотрено иное.\n\n2. В случаях, когда по условиям независимой гарантии допускается ее отзыв или изменение гарантом, такой отзыв или такое изменение производится в форме, в которой выдана гарантия, если иная форма не предусмотрена гарантией.\n\n3. Если по условиям независимой гарантии допускается возможность ее отзыва или изменения гарантом с согласия бенефициара, то обязательство гаранта считается измененным или прекращенным с момента получения гарантом согласия бенефициара.\n\n4. Изменение обязательства гаранта после выдачи независимой гарантии принципалу не затрагивает прав и обязанностей принципала, если он впоследствии не дал согласие на соответствующее изменение.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 371. Отзыв и изменение независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"605b657e9b379fa15182a258bc89938df923d3e7bd54f20577e27407c5c1b89a"},{"code_id":"GK_RF","article_number":"372","version_date":"1994-11-30","article_text":"1. Бенефициар по независимой гарантии не вправе передавать другому лицу право требования к гаранту, если в гарантии не предусмотрено иное.\n\nПередача бенефициаром прав по независимой гарантии другому лицу допускается лишь при условии одновременной уступки тому же лицу прав по основному обязательству.\n\n2. В случае, когда по условиям независимой гарантии допускается передача бенефициаром права требования к гаранту, такая передача возможна лишь с согласия гаранта, если в гарантии не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 372. Передача прав по независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9219ff52a6b87ba978a8d2c22cab3cc23feafaf3528f8b44f08d35f26dac8606"},{"code_id":"GK_RF","article_number":"373","version_date":"1994-11-30","article_text":"Независимая гарантия вступает в силу с момента ее отправки (передачи) гарантом, если в гарантии не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 373. Вступление независимой гарантии в силу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ecb9f8699112add0ac30492896376b37c8ff82fdcf0153a41dff74cfdd4cbdf"},{"code_id":"GK_RF","article_number":"374","version_date":"1994-11-30","article_text":"1. Требование бенефициара об уплате денежной суммы по независимой гарантии должно быть представлено в письменной форме гаранту с приложением указанных в гарантии документов. В требовании или в приложении к нему бенефициар должен указать обстоятельства, наступление которых влечет выплату по независимой гарантии.\n\n2. Требование бенефициара должно быть представлено гаранту до окончания срока действия независимой гарантии.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 374. Представление требования по независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8abf231cf6be5bc356421654b41cb37219af1b34c765d76f7754fb1647cd9d65"},{"code_id":"GK_RF","article_number":"375.1","version_date":"1994-11-30","article_text":"Бенефициар обязан возместить гаранту или принципалу убытки, которые причинены вследствие того, что представленные им документы являлись недостоверными либо предъявленное требование являлось необоснованным.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 375.1. Ответственность бенефициара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e8b32cf19abb4817fc2544401824a5c8047b804ccaf0dd2e33105b19bf84ea56"}]$law7d0025$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
